/* Zennith service worker — keeps the app itself available offline.
 *
 * Firestore already keeps the DATA offline (its local cache and write
 * queue). What it can't do is keep the APP on screen: without this file,
 * refreshing or opening a page with no connection showed the browser's own
 * "Failed to load page" error, because nothing had saved the app's code or
 * page shells.
 *
 * Hand-written on purpose, rather than generated by a build plugin: the
 * build config (the Lovable wrapper) warns against adding plugins, and a
 * file in public/ is served untouched, so this changes nothing about how
 * the app is built or deployed.
 *
 * Strategy:
 *   - /assets/*  — the app's code. Filenames are versioned and never change,
 *                  so once saved they're safe to serve forever (cache-first).
 *   - pages      — network-first: online you always get the latest version;
 *                  offline you get the last saved copy of that page.
 *   - everything cross-origin (Firebase, Google, Resend) is left alone —
 *                  Firestore manages its own offline data.
 *
 * Only registered in production builds (see registerServiceWorker), so it
 * never serves stale code while developing.
 */

// Bump this when the caching strategy itself changes. Deploys don't need a
// bump: new code gets new versioned filenames, and pages are network-first.
const VERSION = "zennith-v1";
const PAGES = `${VERSION}-pages`;
const ASSETS = `${VERSION}-assets`;

self.addEventListener("install", () => {
  // Take over immediately rather than waiting for every tab to close.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Remove caches from older versions of this worker.
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => !k.startsWith(VERSION))
          .map((k) => caches.delete(k)),
      );
      await self.clients.claim();
    })(),
  );
});

function isPage(request) {
  if (request.mode === "navigate") return true;
  const accept = request.headers.get("accept") || "";
  return accept.includes("text/html");
}

/** Pages are saved without their query string, so ?dispense=1 and the plain
 *  URL share one saved copy. */
function pageKey(url) {
  return url.origin + url.pathname;
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Large media is fetched in byte ranges, which the cache handles badly and
  // which isn't needed to use the app offline.
  if (url.pathname.endsWith(".mp4")) return;

  if (isPage(request)) {
    event.respondWith(handlePage(request, url));
    return;
  }

  if (url.pathname.startsWith("/assets/")) {
    event.respondWith(handleAsset(request));
  }
});

async function handlePage(request, url) {
  const cache = await caches.open(PAGES);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(pageKey(url), response.clone());
    return response;
  } catch {
    const saved = await cache.match(pageKey(url));
    if (saved) return saved;
    return offlinePage();
  }
}

async function handleAsset(request) {
  const cache = await caches.open(ASSETS);
  const saved = await cache.match(request);
  if (saved) return saved;
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch {
    return new Response("", { status: 504, statusText: "Offline" });
  }
}

/** Shown only for a page that was never opened while online — so there is
 *  genuinely nothing saved to show. Branded and honest, instead of the
 *  browser's error screen. */
function offlinePage() {
  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Offline · Zennith</title>
<style>
  body{margin:0;min-height:100vh;display:grid;place-items:center;
       font-family:system-ui,sans-serif;background:#0b1530;color:#fff}
  .card{max-width:420px;padding:32px;text-align:center}
  h1{font-size:20px;margin:0 0 8px}
  p{color:#b8c2dc;line-height:1.5;font-size:14px}
  a{display:inline-block;margin-top:16px;padding:10px 18px;border-radius:8px;
    background:#fff;color:#0b1530;text-decoration:none;font-weight:600}
</style></head><body><div class="card">
<h1>You're offline</h1>
<p>This page hasn't been opened on this device yet, so there's nothing saved
to show. Pages you've already visited still work — go back and carry on.
Anything you save will upload when your connection returns.</p>
<a href="javascript:history.back()">Go back</a>
</div></body></html>`;
  return new Response(html, {
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

// ---------------------------------------------------------------------------
// Warming. After login the app sends the list of pages for the user's role,
// and this saves each one in the background — so every screen in the sidebar
// works offline, not just the ones the user happened to click first.
// ---------------------------------------------------------------------------

self.addEventListener("message", (event) => {
  const data = event.data || {};
  if (data.type !== "WARM_PAGES" || !Array.isArray(data.paths)) return;

  event.waitUntil(
    (async () => {
      const cache = await caches.open(PAGES);
      for (const path of data.paths) {
        try {
          const url = new URL(path, self.location.origin);
          const response = await fetch(url.href, {
            headers: { accept: "text/html" },
            credentials: "same-origin",
          });
          if (response.ok) await cache.put(pageKey(url), response);
        } catch {
          // Offline or failed — skip; it'll be saved on a later visit.
        }
      }
    })(),
  );
});
